        const { useState, useEffect, createContext, useContext } = React;

        // API base URL — Vercel hosts the serverless functions, so when running
        // on Firebase hosting we need to call the Vercel domain directly.
        const API_BASE = window.location.hostname === 'listnest.co.il' ? '' : 'https://listnest.co.il';

        // Auth Context
        const AuthContext = createContext(null);

        function AuthProvider({ children }) {
            const [user, setUser] = useState(null);
            const [loading, setLoading] = useState(true);

            useEffect(() => {
                // Handle redirect result from Google sign-in on mobile
                window.firebaseAuth.getRedirectResult(window.auth).catch(() => {});

                const unsubscribe = window.firebaseAuth.onAuthStateChanged(window.auth, (user) => {
                    // Ignore anonymous users - they're only used for child login Firestore access
                    setUser(user?.isAnonymous ? null : user);
                    setLoading(false);
                });
                return () => unsubscribe();
            }, []);

            const value = { user, loading };
            return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
        }

        function useAuth() {
            return useContext(AuthContext);
        }

        // Child Auth Context - for PIN-based child accounts
        const ChildAuthContext = createContext(null);

        function ChildAuthProvider({ children }) {
            const [childUser, setChildUser] = useState(null);
            const [loading, setLoading] = useState(true);

            // Load child session from localStorage on mount
            useEffect(() => {
                try {
                    const savedSession = localStorage.getItem('childSession');
                    if (savedSession) {
                        const session = JSON.parse(savedSession);
                        // Check if session is still valid (24 hours)
                        if (session.expiresAt && new Date(session.expiresAt) > new Date()) {
                            setChildUser(session);
                        } else {
                            localStorage.removeItem('childSession');
                        }
                    }
                } catch (e) {
                    localStorage.removeItem('childSession');
                }
                setLoading(false);
            }, []);

            // Hash PIN with family code as salt
            const hashPin = async (pin, salt) => {
                const encoder = new TextEncoder();
                const data = encoder.encode(pin + salt);
                const hashBuffer = await crypto.subtle.digest('SHA-256', data);
                const hashArray = Array.from(new Uint8Array(hashBuffer));
                return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
            };

            // Login child with PIN
            const loginChild = async (familyId, familyCode, childId, childName, pin) => {
                try {
                    console.log('Child login attempt:', { familyId, familyCode, childId });

                    // Get family document to validate PIN
                    const familyDoc = await window.firestore.getDoc(
                        window.firestore.doc(window.db, 'families', familyId)
                    );

                    if (!familyDoc.exists()) {
                        console.error('Family not found:', familyId);
                        return { success: false, error: 'familyNotFound' };
                    }

                    const familyData = familyDoc.data();
                    const childAccount = familyData.childAccounts?.find(c => c.childId === childId);

                    if (!childAccount) {
                        console.error('Child account not found:', childId);
                        return { success: false, error: 'childNotFound' };
                    }

                    // Verify PIN
                    const pinHash = await hashPin(pin, familyCode);
                    console.log('PIN verification:', { computed: pinHash.substring(0, 10) + '...', stored: childAccount.pinHash?.substring(0, 10) + '...' });

                    if (pinHash !== childAccount.pinHash) {
                        console.error('Invalid PIN');
                        return { success: false, error: 'invalidPin' };
                    }

                    // Create session (24 hour expiry)
                    const session = {
                        childId: childId,
                        displayName: childAccount.displayName,
                        familyId: familyId,
                        familyName: familyData.name,
                        familyCode: familyCode,
                        role: 'limited',
                        familyRole: 'child',
                        isChildAccount: true,
                        loginAt: new Date().toISOString(),
                        expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
                    };

                    // Try to update lastLoginAt in Firestore (don't fail if this fails)
                    try {
                        const updatedChildAccounts = familyData.childAccounts.map(c =>
                            c.childId === childId ? { ...c, lastLoginAt: new Date() } : c
                        );
                        await window.firestore.updateDoc(
                            window.firestore.doc(window.db, 'families', familyId),
                            { childAccounts: updatedChildAccounts }
                        );
                    } catch (updateError) {
                        console.warn('Could not update lastLoginAt:', updateError);
                        // Continue anyway - login still works
                    }

                    localStorage.setItem('childSession', JSON.stringify(session));
                    setChildUser(session);
                    // Sign out anonymous user used for Firestore access
                    if (window.auth.currentUser?.isAnonymous) {
                        try { await window.firebaseAuth.signOut(window.auth); } catch(e) {}
                    }
                    console.log('Child login successful');
                    return { success: true };
                } catch (error) {
                    console.error('Child login error:', error);
                    return { success: false, error: 'loginFailed', details: error.message };
                }
            };

            // Login child with QR token
            const loginChildWithToken = async (token, displayName) => {
                try {
                    // Query families for matching token
                    const familiesRef = window.firestore.collection(window.db, 'families');
                    const snapshot = await window.firestore.getDocs(familiesRef);

                    let targetFamily = null;
                    let targetToken = null;

                    snapshot.forEach(doc => {
                        const data = doc.data();
                        const foundToken = data.childInviteTokens?.find(t =>
                            t.token === token &&
                            !t.usedAt &&
                            new Date(t.expiresAt.toDate ? t.expiresAt.toDate() : t.expiresAt) > new Date()
                        );
                        if (foundToken) {
                            targetFamily = { id: doc.id, ...data };
                            targetToken = foundToken;
                        }
                    });

                    if (!targetFamily || !targetToken) {
                        return { success: false, error: 'invalidToken' };
                    }

                    // Create child account
                    const childId = crypto.randomUUID ? crypto.randomUUID() :
                        'child_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);

                    const newChildAccount = {
                        childId: childId,
                        displayName: displayName,
                        pinHash: null, // No PIN for QR-joined accounts
                        createdAt: new Date(),
                        createdBy: targetToken.createdBy,
                        lastLoginAt: new Date(),
                        role: 'limited',
                        familyRole: 'child',
                        isChildAccount: true
                    };

                    // Mark token as used and add child account
                    const updatedTokens = targetFamily.childInviteTokens.map(t =>
                        t.token === token ? { ...t, usedAt: new Date() } : t
                    );

                    await window.firestore.updateDoc(
                        window.firestore.doc(window.db, 'families', targetFamily.id),
                        {
                            childAccounts: window.firestore.arrayUnion(newChildAccount),
                            childInviteTokens: updatedTokens
                        }
                    );

                    // Create session
                    const session = {
                        childId: childId,
                        displayName: displayName,
                        familyId: targetFamily.id,
                        familyName: targetFamily.name,
                        familyCode: targetFamily.code,
                        role: 'limited',
                        familyRole: 'child',
                        isChildAccount: true,
                        loginAt: new Date().toISOString(),
                        expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
                    };

                    localStorage.setItem('childSession', JSON.stringify(session));
                    setChildUser(session);
                    return { success: true };
                } catch (error) {
                    console.error('Child token login error:', error);
                    return { success: false, error: 'loginFailed' };
                }
            };

            // Logout child
            const logoutChild = () => {
                localStorage.removeItem('childSession');
                setChildUser(null);
            };

            const value = {
                childUser,
                loading,
                loginChild,
                loginChildWithToken,
                logoutChild,
                hashPin
            };

            return <ChildAuthContext.Provider value={value}>{children}</ChildAuthContext.Provider>;
        }

        function useChildAuth() {
            return useContext(ChildAuthContext);
        }

