            freshMeat: { name: 'בשר טרי', icon: '🥩', image: 'https://images.unsplash.com/photo-1603048297172-c92544798d5a?w=200&h=200&fit=crop', unit: 'ק"ג', unitOptions: ['ק"ג', 'גרם', 'יח\''] },
