            const [toasts, setToasts] = useState([]);
            const toastIdRef = React.useRef(0);
            const showToast = React.useCallback((message, type = 'info', duration = 3500) => {
                const id = ++toastIdRef.current;
                setToasts(prev => [...prev.slice(-4), { id, message, type, duration }]);
                setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), duration);
                return id;
            }, []);
            // Undo system
            const [undoAction, setUndoAction] = useState(null);
            const undoTimerRef = React.useRef(null);
            const showUndoToast = React.useCallback((message, onUndo) => {
                if (undoTimerRef.current) clearTimeout(undoTimerRef.current);
                setUndoAction({ message, onUndo });
                undoTimerRef.current = setTimeout(() => setUndoAction(null), 5000);
            }, []);
            const executeUndo = React.useCallback(() => {
                if (undoAction?.onUndo) undoAction.onUndo();
                if (undoTimerRef.current) clearTimeout(undoTimerRef.current);
                setUndoAction(null);
            }, [undoAction]);

