            // Show chat notification
            const showChatNotification = (message) => {
                if (!notificationsEnabled || !('Notification' in window)) return;
                if (Notification.permission !== 'granted') return;

                // Don't show if chat is open and visible
                if (showChat && document.visibilityState === 'visible') return;

                // Special handling for reminder messages
                const isReminder = message.type === 'reminder';
                const title = isReminder
                    ? `🔔 ${t('reminderFromFamily')}`
                    : `💬 ${message.senderName || t('newMessage')}`;
                const body = isReminder
                    ? message.text || t('dontForgetToAdd')
                    : (message.photoUrl ? `📷 ${t('sentPhoto')}` : message.text || t('newMessage'));

                try {
                    const notification = new Notification(title, {
                        body: body,
                        icon: isReminder ? '🔔' : '🛒',
                        badge: '🛒',
                        tag: isReminder ? 'reminder-message' : 'chat-message',
                        renotify: true,
                        vibrate: isReminder ? [300, 100, 300, 100, 300] : [200, 100, 200]
                    });

                    notification.onclick = () => {
                        window.focus();
                        setShowChat(true);
                        notification.close();
                    };

                    // Auto close after 5 seconds (8 seconds for reminders)
                    setTimeout(() => notification.close(), isReminder ? 8000 : 5000);
                } catch (error) {
                    console.error('Notification error:', error);
                }
            };

